import { Input, Message } from "./types";

export const inputs = ["/patrol_state"];
export const output = "/foxglove/patrol_mode_str";

export default function script(
  event: Input<"/patrol_state">
): Message<"std_msgs/String"> {
  try {
    const d = JSON.parse(event.message.data);
    return { data: String(d.mode ?? "IDLE") };
  } catch {
    return { data: "IDLE" };
  }
}

battery_extractor.sourceCode:
import { Input, Message } from "./types";

export const inputs = ["/robot/state"];
export const output = "/foxglove/battery";

export default function script(
  event: Input<"/robot/state">
): Message<"std_msgs/Float32"> {
  try {
    const d = JSON.parse(event.message.data);
    const b = Number(d.battery ?? 100);
    return { data: Math.max(0, Math.min(100, b)) };
  } catch {
    return { data: 0 };
  }
}

