import { Input, Message } from "./types";

type Item = { id?: string; x: number; y: number; z?: number; level?: string; label?: string };

export const inputs = ["/intruder_states"];
export const output = "/foxglove/intruder_markers";

export default function script(
  event: Input<"/intruder_states">
): Message<"foxglove.SceneUpdate"> {
  let items: Item[] = [];
  try {
    const d = JSON.parse(event.message.data);
    items = Array.isArray(d) ? d : (d.items ?? []);
  } catch {}
  return {
    deletions: [],
    entities: items.map((it, i) => ({
      id: `intruder_${it.id ?? i}`,
      timestamp: event.receiveTime,
      frame_id: "world",
      frame_locked: false,
      lifetime: { sec: 3, nsec: 0 },
      metadata: [],
      arrows: [], cubes: [], lines: [], cylinders: [], texts: [],
      models: [], triangles: [],
      spheres: [{
        pose: {
          position: { x: it.x, y: it.y, z: it.z ?? 0.5 },
          orientation: { x: 0, y: 0, z: 0, w: 1 },
        },
        size: { x: 1.2, y: 1.2, z: 1.2 },
        color: (it.level || "").toUpperCase() === "ALERT"
          ? { r: 1.0, g: 0.2, b: 0.2, a: 0.85 }
          : { r: 1.0, g: 0.85, b: 0.3, a: 0.7 },
      }],
    })),
  };
}

landmarks_to_scene.sourceCode:
import { Input, Message } from "./types";

type LM = { home?: {x:number,y:number,z?:number}; goal?: {x:number,y:number,z?:number}; arrive_box?: number };

export const inputs = ["/scene/landmarks"];
export const output = "/foxglove/landmark_markers";

export default function script(
  event: Input<"/scene/landmarks">
): Message<"foxglove.SceneUpdate"> {
  let lm: LM = {};
  try { lm = JSON.parse(event.message.data); } catch {}
  const entities: any[] = [];
  if (lm.home) entities.push({
    id: "home", timestamp: event.receiveTime, frame_id: "world", frame_locked: false,
    lifetime: { sec: 0, nsec: 0 }, metadata: [],
    arrows: [], lines: [], cylinders: [], models: [], triangles: [], spheres: [],
    cubes: [{
      pose: { position: { x: lm.home.x, y: lm.home.y, z: (lm.home.z ?? 0) + 0.5 }, orientation: { x:0, y:0, z:0, w:1 } },
      size: { x: 2, y: 2, z: 1 },
      color: { r: 0.2, g: 1.0, b: 0.4, a: 0.85 },
    }],
    texts: [{
      pose: { position: { x: lm.home.x, y: lm.home.y, z: (lm.home.z ?? 0) + 2.5 }, orientation: { x:0,y:0,z:0,w:1 } },
      billboard: true, font_size: 0.8, scale_invariant: false,
      color: { r:0.2, g:1.0, b:0.4, a:1.0 }, text: "HOME",
    }],
  });
  if (lm.goal) entities.push({
    id: "goal", timestamp: event.receiveTime, frame_id: "world", frame_locked: false,
    lifetime: { sec: 0, nsec: 0 }, metadata: [],
    arrows: [], lines: [], models: [], triangles: [], spheres: [],
    cubes: [{
      pose: { position: { x: lm.goal.x, y: lm.goal.y, z: (lm.goal.z ?? 0) + 0.5 }, orientation: { x:0, y:0, z:0, w:1 } },
      size: { x: 2, y: 2, z: 1 },
      color: { r: 1.0, g: 0.3, b: 0.3, a: 0.85 },
    }],
    cylinders: lm.arrive_box ? [{
      pose: { position: { x: lm.goal.x, y: lm.goal.y, z: (lm.goal.z ?? 0) }, orientation: { x:0,y:0,z:0,w:1 } },
      size: { x: lm.arrive_box * 2, y: lm.arrive_box * 2, z: 0.1 },
      bottom_scale: 1.0, top_scale: 1.0,
      color: { r: 1.0, g: 0.3, b: 0.3, a: 0.25 },
    }] : [],
    texts: [{
      pose: { position: { x: lm.goal.x, y: lm.goal.y, z: (lm.goal.z ?? 0) + 2.5 }, orientation: { x:0,y:0,z:0,w:1 } },
      billboard: true, font_size: 0.8, scale_invariant: false,
      color: { r:1.0, g:0.4, b:0.4, a:1.0 }, text: "GOAL",
    }],
  });
  return { deletions: [], entities };
}
